{
  "story": "How does merge sort build a sorted array? Start with the highlighted input on a fixed split-and-merge map. Divide into singletons, then merge sorted runs by choosing the smaller front value. Track the final prefix and comparison count. The completed merge shows why choosing the smaller front preserves order.",
  "aha": {
    "stateId": "complete",
    "observation": "Choosing the smaller front preserves sorted order during merging; starting from singletons lets repeated merges sort the entire input."
  },
  "layout": {
    "preset": "stepper-states/algorithm-collection",
    "width": 640
  },
  "parts": [
    {
      "id": "active-explanation",
      "kind": "active-callout",
      "presentation": "Place explanation and status above the experiment, with an anchored leader to the target. Text supplies the status line; reason explains the mechanism.",
      "bind": {
        "target": "state.calloutRegion",
        "text": "state.sentence",
        "reason": "state.why"
      }
    },
    {
      "id": "state-rail",
      "kind": "step-rail",
      "presentation": "Use short labels in a wrapping rail with a distinct active step. Keep all progress here. Parameter-control budget: zero, excluding navigation and Reset.",
      "bind": {
        "active": "state.id",
        "items": "variant.states"
      }
    },
    {
      "id": "merge-map",
      "kind": "fixed-picture",
      "presentation": "Use the canonical split-and-merge arrangement with fixed positions and equal-sized array cells. All runs remain visible as a roadmap; highlight only active regions. Persistent runs provide comparison context without a ghost. Reserve readable labels at native width.",
      "bind": {
        "active": "state.active",
        "links": "variant.links",
        "regions": "variant.regions"
      }
    },
    {
      "id": "merge-evidence",
      "kind": "value-readout",
      "presentation": "Use a fixed two-column grid below the picture. Preserve field positions across states. Counts derive from the fixed input and traced merges. Report each measurement only here; retain exact integer counts without rounding.",
      "bind": {
        "values": "state.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "step",
      "kind": "index",
      "items": "variant.states",
      "label": "Merge sort step",
      "presentation": "Use Previous and Next, retaining those names when disabled at boundaries. Default to the first state; advance one state within the listed bounds. Provide visible focus and Left/Right keyboard operation. Put navigation instructions above the experiment. Every state persists until learner action; never autoplay. Reference captures show complete."
    },
    {
      "id": "reset",
      "kind": "reset",
      "label": "Reset",
      "presentation": "Restore the first state and all defaults. Support Enter and Space with visible keyboard focus."
    }
  ],
  "data": {
    "variants": [
      {
        "label": "Fixed distinct integers, ascending order",
        "regions": [
          {
            "id": "input",
            "label": "Input",
            "values": ["4", "1", "3", "2"]
          },
          {
            "id": "left-half",
            "label": "Left half",
            "values": ["4", "1"]
          },
          {
            "id": "right-half",
            "label": "Right half",
            "values": ["3", "2"]
          },
          {
            "id": "singleton-a",
            "label": "Singleton A",
            "values": ["4"]
          },
          {
            "id": "singleton-b",
            "label": "Singleton B",
            "values": ["1"]
          },
          {
            "id": "singleton-c",
            "label": "Singleton C",
            "values": ["3"]
          },
          {
            "id": "singleton-d",
            "label": "Singleton D",
            "values": ["2"]
          },
          {
            "id": "left-run",
            "label": "Sorted left run",
            "values": ["1", "4"]
          },
          {
            "id": "right-run",
            "label": "Sorted right run",
            "values": ["2", "3"]
          },
          {
            "id": "result",
            "label": "Sorted result",
            "values": ["1", "2", "3", "4"]
          }
        ],
        "links": [
          {
            "from": "input",
            "to": "left-half",
            "label": "split"
          },
          {
            "from": "input",
            "to": "right-half",
            "label": "split"
          },
          {
            "from": "left-half",
            "to": "singleton-a",
            "label": "split"
          },
          {
            "from": "left-half",
            "to": "singleton-b",
            "label": "split"
          },
          {
            "from": "right-half",
            "to": "singleton-c",
            "label": "split"
          },
          {
            "from": "right-half",
            "to": "singleton-d",
            "label": "split"
          },
          {
            "from": "singleton-a",
            "to": "left-run",
            "label": "merge"
          },
          {
            "from": "singleton-b",
            "to": "left-run",
            "label": "merge"
          },
          {
            "from": "singleton-c",
            "to": "right-run",
            "label": "merge"
          },
          {
            "from": "singleton-d",
            "to": "right-run",
            "label": "merge"
          },
          {
            "from": "left-run",
            "to": "result",
            "label": "merge"
          },
          {
            "from": "right-run",
            "to": "result",
            "label": "merge"
          }
        ],
        "states": [
          {
            "id": "input",
            "label": "Start with the unsorted input",
            "short": "Input",
            "sentence": "The input is unsorted; the pale roadmap shows the runs used during splitting and merging.",
            "why": "Sort ascending with fixed, distinct integers. Count only comparisons between run fronts and item placements during merges; splitting creates views.",
            "active": ["input"],
            "calloutRegion": "input",
            "readouts": [
              {
                "id": "front-comparison",
                "label": "Front comparison",
                "value": "Not started"
              },
              {
                "id": "comparisons",
                "label": "Cumulative key comparisons",
                "value": "0 comparisons"
              },
              {
                "id": "placements",
                "label": "Cumulative merge placements",
                "value": "0 item placements"
              },
              {
                "id": "final-prefix",
                "label": "Final merge prefix",
                "value": "[]"
              }
            ]
          },
          {
            "id": "split",
            "label": "Divide into halves",
            "short": "Halves",
            "sentence": "Divide the input into a left half and a right half without rearranging their values.",
            "why": "Splitting reduces the problem size but does not sort either half.",
            "active": ["left-half", "right-half"],
            "calloutRegion": "left-half",
            "readouts": [
              {
                "id": "front-comparison",
                "label": "Front comparison",
                "value": "None during splitting"
              },
              {
                "id": "comparisons",
                "label": "Cumulative key comparisons",
                "value": "0 comparisons"
              },
              {
                "id": "placements",
                "label": "Cumulative merge placements",
                "value": "0 item placements"
              },
              {
                "id": "final-prefix",
                "label": "Final merge prefix",
                "value": "[]"
              }
            ]
          },
          {
            "id": "singletons",
            "label": "Reach singleton runs",
            "short": "Singles",
            "sentence": "Continue splitting until every run contains a single item.",
            "why": "Every singleton is already sorted, providing the base case for merging.",
            "active": [
              "singleton-a",
              "singleton-b",
              "singleton-c",
              "singleton-d"
            ],
            "calloutRegion": "singleton-a",
            "readouts": [
              {
                "id": "front-comparison",
                "label": "Front comparison",
                "value": "None during splitting"
              },
              {
                "id": "comparisons",
                "label": "Cumulative key comparisons",
                "value": "0 comparisons"
              },
              {
                "id": "placements",
                "label": "Cumulative merge placements",
                "value": "0 item placements"
              },
              {
                "id": "final-prefix",
                "label": "Final merge prefix",
                "value": "[]"
              }
            ]
          },
          {
            "id": "merge-left",
            "label": "Merge the left singletons",
            "short": "Left run",
            "sentence": "Merge the left singletons: place the smaller front first, then copy the remaining tail.",
            "why": "After either input empties, its partner's remaining items need no further comparisons.",
            "active": ["singleton-a", "singleton-b", "left-run"],
            "calloutRegion": "left-run",
            "readouts": [
              {
                "id": "front-comparison",
                "label": "Front comparison",
                "value": "4 > 1; choose right"
              },
              {
                "id": "comparisons",
                "label": "Cumulative key comparisons",
                "value": "1 comparison"
              },
              {
                "id": "placements",
                "label": "Cumulative merge placements",
                "value": "2 item placements"
              },
              {
                "id": "final-prefix",
                "label": "Final merge prefix",
                "value": "[]"
              }
            ]
          },
          {
            "id": "merge-right",
            "label": "Merge the right singletons",
            "short": "Right run",
            "sentence": "Apply the same merge rule to the right singletons.",
            "why": "Both resulting runs are sorted, so their fronts reveal their smallest remaining items.",
            "active": ["singleton-c", "singleton-d", "right-run"],
            "calloutRegion": "right-run",
            "readouts": [
              {
                "id": "front-comparison",
                "label": "Front comparison",
                "value": "3 > 2; choose right"
              },
              {
                "id": "comparisons",
                "label": "Cumulative key comparisons",
                "value": "2 comparisons"
              },
              {
                "id": "placements",
                "label": "Cumulative merge placements",
                "value": "4 item placements"
              },
              {
                "id": "final-prefix",
                "label": "Final merge prefix",
                "value": "[]"
              }
            ]
          },
          {
            "id": "take-left",
            "label": "Begin the final merge",
            "short": "Pick left",
            "sentence": "Compare the sorted runs' fronts and append the smaller left front to the final prefix.",
            "why": "Each run is sorted, so the smaller front is the smallest item remaining anywhere.",
            "active": ["left-run", "right-run"],
            "calloutRegion": "left-run",
            "readouts": [
              {
                "id": "front-comparison",
                "label": "Front comparison",
                "value": "1 < 2; choose left"
              },
              {
                "id": "comparisons",
                "label": "Cumulative key comparisons",
                "value": "3 comparisons"
              },
              {
                "id": "placements",
                "label": "Cumulative merge placements",
                "value": "5 item placements"
              },
              {
                "id": "final-prefix",
                "label": "Final merge prefix",
                "value": "[1]"
              }
            ]
          },
          {
            "id": "take-right-first",
            "label": "Compare the unconsumed fronts",
            "short": "Pick right",
            "sentence": "Advance only the left run's front, compare again, and append the smaller right front.",
            "why": "Ignore consumed items. The prefix remains sorted because the selected front cannot precede anything already emitted.",
            "active": ["left-run", "right-run"],
            "calloutRegion": "right-run",
            "readouts": [
              {
                "id": "front-comparison",
                "label": "Front comparison",
                "value": "4 > 2; choose right"
              },
              {
                "id": "comparisons",
                "label": "Cumulative key comparisons",
                "value": "4 comparisons"
              },
              {
                "id": "placements",
                "label": "Cumulative merge placements",
                "value": "6 item placements"
              },
              {
                "id": "final-prefix",
                "label": "Final merge prefix",
                "value": "[1, 2]"
              }
            ]
          },
          {
            "id": "take-right-second",
            "label": "Choose the right front again",
            "short": "Right again",
            "sentence": "Advance the right run's front and compare again; its next item also belongs before the left front.",
            "why": "The unconsumed portion of each run stays sorted, so inspecting only its front remains sufficient.",
            "active": ["left-run", "right-run"],
            "calloutRegion": "right-run",
            "readouts": [
              {
                "id": "front-comparison",
                "label": "Front comparison",
                "value": "4 > 3; choose right"
              },
              {
                "id": "comparisons",
                "label": "Cumulative key comparisons",
                "value": "5 comparisons"
              },
              {
                "id": "placements",
                "label": "Cumulative merge placements",
                "value": "7 item placements"
              },
              {
                "id": "final-prefix",
                "label": "Final merge prefix",
                "value": "[1, 2, 3]"
              }
            ]
          },
          {
            "id": "complete",
            "label": "Append the tail and inspect the result",
            "short": "Complete",
            "sentence": "The right run is empty; append the remaining left tail to complete the sorted result.",
            "why": "Every choice preserved a sorted prefix. Merging sorted runs therefore produces another sorted run, starting from the singleton base cases.",
            "active": ["result"],
            "calloutRegion": "result",
            "readouts": [
              {
                "id": "front-comparison",
                "label": "Front comparison",
                "value": "Right run empty; no comparison"
              },
              {
                "id": "comparisons",
                "label": "Cumulative key comparisons",
                "value": "5 comparisons = 1 left + 1 right + 3 final"
              },
              {
                "id": "placements",
                "label": "Cumulative merge placements",
                "value": "8 item placements"
              },
              {
                "id": "final-prefix",
                "label": "Final merge prefix",
                "value": "[1, 2, 3, 4]"
              }
            ]
          }
        ]
      }
    ]
  }
}
